<script lang="ts">
  import {onMount,tick} from 'svelte';
  import {editor} from '../core/editor.svelte';
  import {chartFromElement,type Chart} from '../core/charts';
  import {chartValueStep,chartWithPointValue,draggedChartValue,type ChartDragGeometry} from '../core/chart-drag';
  import {formatChartValue} from '../core/chart-style';
  import type {SlideElement} from '../core/model';
  import type {ChartPoint} from '../core/chart-points';
  import {holdPointerCursor} from '../pointer-cursor';
  import {resizeCursor} from '../core/interactions';
  let {element,scale,disabled=false,onpreview}:{element:SlideElement;scale:number;disabled?:boolean;onpreview:(chart:Chart|null)=>void}=$props();
  let marker=$state<HTMLDivElement>(),root:HTMLElement|undefined;
  type Drag={id:number;clientX:number;clientY:number;x:number;y:number;matrix:DOMMatrix;point:ChartPoint;base:Chart;geometry:ChartDragGeometry;revision:number;deckId:string;slideId:string;scale:number;active:boolean;value:number};
  let drag=$state<Drag|null>(null),release:(()=>void)|undefined,frame=0,suppressUntil=0,focusPoint:ChartPoint|undefined;
  function targets(){return Array.from(root?.querySelectorAll<SVGElement>('[data-chart-point]')??[]);}
  function point(e:Event):{node:SVGElement;point:ChartPoint}|undefined{if(!(e.target instanceof Element))return;let n=e.target.closest<SVGElement>('[data-chart-point]');if(!n||!root?.contains(n))return;if(e instanceof PointerEvent&&n.hasAttribute('data-chart-line-hit')){let distance=Infinity;for(const p of targets().filter(p=>p.hasAttribute('data-chart-line-hit'))){const r=p.getBoundingClientRect(),d=Math.hypot(e.clientX-r.x-r.width/2,e.clientY-r.y-r.height/2);if(d<distance){n=p;distance=d;}}}return {node:n,point:{series:Number(n.dataset.chartSeries),category:Number(n.dataset.chartCategory)}};}
  function valid(g:Drag){return editor.deck?.id===g.deckId&&editor.slide?.id===g.slideId&&editor.deck?.revision===g.revision&&!element.locked&&!disabled&&scale===g.scale;}
  function restore(){if(!focusPoint)return;const p=focusPoint,n=targets().find(n=>Number(n.dataset.chartSeries)===p.series&&Number(n.dataset.chartCategory)===p.category);if(n){n.focus({preventScroll:true});focusPoint=undefined;}}
  function clear(cancel=false){const g=drag;drag=null;cancelAnimationFrame(frame);release?.();release=undefined;onpreview(null);if(g&&root?.hasPointerCapture(g.id))root.releasePointerCapture(g.id);if(g?.active){suppressUntil=performance.now()+350;focusPoint=g.point;void tick().then(restore);}if(cancel&&g?.active)editor.notify('Chart edit canceled');}
  function down(e:PointerEvent){if(disabled||element.locked||e.button!==0||drag)return;const hit=point(e),svg=root?.querySelector<SVGSVGElement>('svg[data-chart-drag]'),matrix=svg?.getScreenCTM();if(!hit||!svg||!matrix)return;let geometry:ChartDragGeometry;try{geometry=JSON.parse(svg.dataset.chartDrag!);}catch{return;}e.preventDefault();e.stopPropagation();const base=chartFromElement(element),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());hit.node.focus({preventScroll:true});drag={id:e.pointerId,clientX:e.clientX,clientY:e.clientY,x:p.x,y:p.y,matrix:matrix.inverse(),point:hit.point,base,geometry,revision:editor.deck!.revision,deckId:editor.deck!.id,slideId:editor.slide!.id,scale,active:false,value:base.series[hit.point.series].values[hit.point.category]};}
  function preview(g:Drag){try{const chart=chartWithPointValue(g.base,g.point,g.value);onpreview(g.geometry.kind==='axis'?{...chart,axisRange:{min:g.geometry.min,max:g.geometry.max}}:chart);}catch{/* Keep the last valid preview. */}}
  function move(e:PointerEvent){const g=drag;if(!g||g.id!==e.pointerId)return;if(!valid(g)){clear(true);return;}if(!g.active&&Math.hypot(e.clientX-g.clientX,e.clientY-g.clientY)<(e.pointerType==='touch'?8:4))return;e.preventDefault();e.stopPropagation();if(!g.active){g.active=true;root?.setPointerCapture(e.pointerId);release=holdPointerCursor(resizeCursor(element,g.geometry.kind==='axis'&&g.geometry.horizontal?'e':'s'));}const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(g.matrix);g.value=draggedChartValue(g.base,g.point,g.geometry,{x:g.x,y:g.y},p,e.altKey);cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(drag===g)preview(g);});}
  function up(e:PointerEvent){const g=drag;if(!g||g.id!==e.pointerId)return;const active=g.active,allowed=valid(g);clear();if(!active)return;e.preventDefault();e.stopPropagation();if(allowed&&g.value!==g.base.series[g.point.series].values[g.point.category]){try{const chart=chartWithPointValue(g.base,g.point,g.value);editor.commit([{op:'update_element',slideId:g.slideId,elementId:element.id,patch:{chart,values:undefined}}],'','manual',g.revision);}catch(error){editor.notify((error as Error).message,'warning');}}}
  function key(e:KeyboardEvent){if(e.isComposing)return;if(e.key==='Escape'&&drag){e.preventDefault();e.stopPropagation();clear(true);return;}if(disabled||e.ctrlKey||e.metaKey)return;const hit=point(e),direction=e.key==='+'||e.key==='='||e.altKey&&e.key==='ArrowUp'?1:e.key==='-'||e.altKey&&e.key==='ArrowDown'?-1:0;if(!hit||!direction)return;e.preventDefault();e.stopPropagation();const chart=chartFromElement(element),current=chart.series[hit.point.series].values[hit.point.category],value=Number((current+direction*chartValueStep(chart)*(e.shiftKey?10:1)).toPrecision(12));try{const next=chartWithPointValue(chart,hit.point,value);focusPoint=hit.point;editor.commit([{op:'update_element',slideId:editor.slide!.id,elementId:element.id,patch:{chart:next,values:undefined}}]);}catch(error){editor.notify((error as Error).message,'warning');}}
  function click(e:MouseEvent){if(performance.now()<suppressUntil){e.preventDefault();e.stopPropagation();}}
  function cancel(e:PointerEvent){if(e.pointerId===drag?.id)clear(true);}
  function portal(n:HTMLElement){document.body.append(n);return {destroy(){n.remove();}};}
  $effect(()=>{element;scale;disabled;if(drag&&!valid(drag))clear(true);});
  onMount(()=>{root=marker?.parentElement??undefined;root?.addEventListener('pointerdown',down,true);root?.addEventListener('click',click,true);root?.addEventListener('keydown',key,true);window.addEventListener('keydown',key,true);window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true);window.addEventListener('pointercancel',cancel,true);const rendered=()=>restore(),abandon=()=>clear(true);window.addEventListener('deck-studio-chart-rendered',rendered);window.addEventListener('blur',abandon);window.addEventListener('resize',abandon);return()=>{clear();root?.removeEventListener('pointerdown',down,true);root?.removeEventListener('click',click,true);root?.removeEventListener('keydown',key,true);window.removeEventListener('keydown',key,true);window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true);window.removeEventListener('pointercancel',cancel,true);window.removeEventListener('deck-studio-chart-rendered',rendered);window.removeEventListener('blur',abandon);window.removeEventListener('resize',abandon);};});
</script>
<div bind:this={marker} class="chart-drag-hook"></div>
{#if drag?.active}<div use:portal class="chart-drag-value" role="status" style:left={`${Math.max(12,Math.min(innerWidth-220,drag.clientX+12))}px`} style:top={`${Math.max(12,Math.min(innerHeight-80,drag.clientY-72))}px`}><strong>{drag.base.labels[drag.point.category]} · {formatChartValue(drag.base,drag.value)}</strong><span>Release to save · Esc cancels</span></div>{/if}
<style>.chart-drag-hook{display:none}.chart-drag-value{position:fixed;z-index:170;pointer-events:none;display:flex;flex-direction:column;gap:4px;max-width:208px;padding:8px 12px;border:1px solid var(--component-border);border-radius:var(--r-popover);background:var(--surface-overlay);color:var(--text-primary);box-shadow:var(--shadow-floating)}.chart-drag-value strong{font:600 var(--ui-label)/1.4 var(--font-ui)}.chart-drag-value span{font:var(--ui-meta)/1.4 var(--font-ui);color:var(--text-secondary)}</style>
